TP.register({id:"lp5-gk",lp:5,grade:"K",mode:"curriculum",checks:4,nextGrade:"1st grade",build(E){const F=E.F;const TENT="tent",CRATE="box",FISH="fish",WHALE="whale",SNOW="snowflake",FLAG="flag",DOG="dog",RADIO="radio",EAR="ear",SKIS="skis",BOOT="boot",SUN="sun",PHONE="phone",TALK="speak",BOOK="📖",CLAP="hand",BALL="soccerBall",PARK="tree";const ic=(e,px)=>(F.icon||F.pic2)(e,px)||e;const unit=(e,px,sp)=>`<span style="display:inline-block;margin-right:${sp}">${(F.icon||F.pic2)(e,px)||e}</span>`;const CAMP="A team of scientists went far away to study the ice. They flew in a small plane and landed on a flat field of snow. They put up four red tents in a circle. Red is easy to see when the snow blows. Every day they walked out with flags on sticks to mark a safe path back to camp. At night the sky above the tents glowed green and blue.";const WHALES="Whales live in the cold sea near the ice. A whale is not a fish. A whale breathes air, the same way you do. It swims up to the top of the water to take a breath. Then it dives back down to look for food. Some whales sing to each other under the water.";const NAME_LETTERS=["S","a","G","t","O","f","m","I","p","d"];const SOUND_LETTERS=["r","A","s","k","i","N","b","o","w","g"];const DISP="font-family:var(--font-display);font-weight:800";const WRITE_DIR="Draw and write on your paper. Hold it up when you finish.";const LINE_STYLE="font-size:2.2rem;line-height:1.9;margin:0 auto;width:fit-content";function wordGrid(ws){return`<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:6px 0 10px">${ws.map(w=>`<div style="border:3px solid var(--line);border-radius:16px;text-align:center;padding:14px 6px;background:var(--surface);${DISP};font-size:clamp(2rem,6vw,3.4rem)">${w}</div>`).join("")}</div>`}const K_EYE=window.TP_ICON_EYE||((x,y,r)=>`<circle cx="${x}" cy="${y}" r="${r||4.4}" fill="#4A332A"/><circle cx="${x-1.4}" cy="${y-1.7}" r="1.6" fill="#fff"/>`);const K_BLUSH=window.TP_ICON_BLUSH||((x,y)=>`<ellipse cx="${x}" cy="${y}" rx="6.5" ry="4.2" fill="#F49AAB" opacity=".9"/>`);const K_SMILE=window.TP_ICON_SMILE||((x,y,w)=>`<path d="M${x-w} ${y} q${w} ${w} ${w*2} 0" fill="none" stroke="#4A332A" stroke-width="2.6" stroke-linecap="round"/>`);const K_FACE=window.TP_ICON_FACE||((cx,cy,sp,mw)=>K_EYE(cx-sp,cy)+K_EYE(cx+sp,cy)+K_BLUSH(cx-sp-7,cy+9)+K_BLUSH(cx+sp+7,cy+9)+K_SMILE(cx,cy+9,mw||4));const K_WELD=window.TP_ICON_WELD||((parts,st)=>parts.map(f=>f(st)).join("")+parts.map(f=>f('stroke="none"')).join(""));const n1=v=>Math.round(v*10)/10;const at=(x,y,k,inner)=>`<g transform="translate(${n1(x)} ${n1(y)}) scale(${n1(k)})">${inner}</g>`;const face=(x,y,k,sp,mw)=>at(x,y,k,K_FACE(0,0,sp,mw||4));const eyeAt=(x,y,k,r)=>at(x,y,k,K_EYE(0,0,r));const blushAt=(x,y,k)=>at(x,y,k,K_BLUSH(0,0));const INK="#6B4A3C",RED="#DE5A48",GOLD="#F2CE86",WOOD="#E7C49A",WOOD_L="#D0A471",ICEF="#E8F4FF",ICE_D="#5E8FA8",FUR="#C2C7CE",FUR_L="#E8EBEF",STEEL="#CBD8E2";function sealShape(x,y,s){const sw=Math.max(2,s*.03).toFixed(1),ST=`stroke="${INK}" stroke-width="${sw}" stroke-linejoin="round"`,k=s/100;const px=d=>(x+s*d).toFixed(1),py=d=>(y+s*d).toFixed(1),m=d=>(s*d).toFixed(1),P=(a,b)=>`${px(a)} ${py(b)}`;const body=st=>`<ellipse cx="${px(.03)}" cy="${py(.12)}" rx="${m(.33)}" ry="${m(.19)}" fill="${FUR}" ${st}/>`;const head=st=>`<circle cx="${px(-.3)}" cy="${py(-.07)}" r="${m(.2)}" fill="${FUR}" ${st}/>`;return`<path d="M${P(.26,.05)} Q${P(.45,-.12)} ${P(.49,-.02)} Q${P(.52,.1)} ${P(.44,.22)} Q${P(.34,.18)} ${P(.26,.05)} Z" fill="${FUR}" ${ST}/>`+K_WELD([body,head],ST)+`<ellipse cx="${px(-.01)}" cy="${py(.2)}" rx="${m(.23)}" ry="${m(.09)}" fill="${FUR_L}"/><ellipse cx="${px(-.03)}" cy="${py(.27)}" rx="${m(.13)}" ry="${m(.055)}" fill="${FUR}" stroke="${INK}" stroke-width="${Math.max(1.8,s*.025).toFixed(1)}"/>`+eyeAt(px(-.37),py(-.13),k)+eyeAt(px(-.23),py(-.13),k)+blushAt(px(-.45),py(-.03),k)+blushAt(px(-.15),py(-.03),k)+`<ellipse cx="${px(-.3)}" cy="${py(.01)}" rx="${m(.1)}" ry="${m(.07)}" fill="${FUR_L}" stroke="${INK}" stroke-width="${Math.max(1.6,s*.022).toFixed(1)}"/><ellipse cx="${px(-.3)}" cy="${py(-.015)}" rx="${m(.035)}" ry="${m(.026)}" fill="#4A332A"/><path d="M${P(-.3,.015)} q${m(-.045)} ${m(.055)} ${m(-.085)} ${m(.012)} M${P(-.3,.015)} q${m(.045)} ${m(.055)} ${m(.085)} ${m(.012)}" fill="none" stroke="#4A332A" stroke-width="${Math.max(1.4,s*.02).toFixed(1)}" stroke-linecap="round"/><path d="M${P(-.4,.005)} L${P(-.52,-.025)} M${P(-.4,.04)} L${P(-.51,.06)}" fill="none" stroke="${INK}" stroke-width="${Math.max(1.2,s*.018).toFixed(1)}" stroke-linecap="round"/>`}function sledShape(x,y,s){const sw=Math.max(2.2,s*.045).toFixed(1),x0=x-s/2,y0=y-s*.19,k=s/100;const run=`M${(x0+s*.02).toFixed(1)} ${(y0+s*.4).toFixed(1)} H${(x0+s*.8).toFixed(1)} q${(s*.16).toFixed(1)} 0 ${(s*.18).toFixed(1)} ${(-s*.14).toFixed(1)}`;return`<rect x="${(x0+s*.06).toFixed(1)}" y="${y0.toFixed(1)}" width="${(s*.8).toFixed(1)}" height="${(s*.26).toFixed(1)}" rx="${(s*.1).toFixed(1)}" fill="${RED}" stroke="${INK}" stroke-width="${sw}"/><path d="M${(x0+s*.22).toFixed(1)} ${(y0+s*.26).toFixed(1)} v${(s*.14).toFixed(1)} M${(x0+s*.7).toFixed(1)} ${(y0+s*.26).toFixed(1)} v${(s*.14).toFixed(1)}" stroke="${INK}" stroke-width="${sw}" stroke-linecap="round"/><path d="${run}" fill="none" stroke="${INK}" stroke-width="${Math.max(4,s*.085).toFixed(1)}" stroke-linecap="round"/><path d="${run}" fill="none" stroke="${STEEL}" stroke-width="${Math.max(2,s*.045).toFixed(1)}" stroke-linecap="round"/>`+face(x,y-s*.085,k*.78,11,3.6)}const sealPic=w=>`<svg viewBox="0 0 ${w} ${Math.round(w*.66)}" width="${w}" style="vertical-align:middle" role="img" aria-label="a seal">${window.TP_P5.fit("seal",w/2,w*.33,w,w*.66)}</svg>`;const sledPic=w=>`<svg viewBox="0 0 ${w} ${Math.round(w*.62)}" width="${w}" style="vertical-align:middle" role="img" aria-label="a sled">${window.TP_P5.fit("sled",w/2,w*.31,w,w*.62)}</svg>`;function grp(e,n,per,sz){const one=ic(e,Math.round(parseFloat(sz||"2.6rem")*16)),rows=[];for(let i=0;i<n;i+=per)rows.push(Array(Math.min(per,n-i)).fill(one).join(""));return`<span style="display:inline-block;border:3px solid var(--line);border-radius:18px;padding:10px 14px;background:var(--surface);font-size:${sz||"2.6rem"};line-height:1.3;letter-spacing:.1em;text-align:left;vertical-align:middle;font-weight:400" role="img" aria-label="a group of ${n} pictures">${rows.join("<br>")}</span>`}function scatter(e,n,seed){const pts=[];let x=seed,tries=0,gap=64;const rnd=()=>{x=(x*9301+49297)%233280;return x/233280};while(pts.length<n){const p=[40+rnd()*260,44+rnd()*172];if(pts.every(q=>Math.hypot(q[0]-p[0],q[1]-p[1])>gap))pts.push(p);if(++tries>4e3){tries=0;gap-=4}}return`<svg viewBox="0 0 340 260" width="330" role="img" aria-label="a scattered group of ${n} pictures"><rect x="4" y="4" width="332" height="252" rx="22" fill="var(--surface)" stroke="var(--line)" stroke-width="3"/>${pts.map(p=>e==="SEAL"?sealShape(Number(p[0].toFixed(0)),Number(p[1].toFixed(0)),52):F.picXY(Number(p[0].toFixed(0)),Number(p[1].toFixed(0)),e,38)||`<text x="${p[0].toFixed(0)}" y="${p[1].toFixed(0)}" font-size="38" text-anchor="middle" dominant-baseline="central">${e}</text>`).join("")}</svg>`}const DECKS=[];function picDeck(cards,notes){let i=0;const d={reset(){i=0},render(){return`<div style="text-align:center"><p style="margin:0">Card ${i+1} of ${cards.length}</p><div style="margin:14px 0 18px;display:flex;justify-content:center;align-items:center;gap:22px;flex-wrap:wrap">${cards[i]}</div><div class="row center"><button class="btn ghost" data-d="-1" ${i===0?"disabled":""}>Back</button><button class="btn ghost" data-d="1" ${i===cards.length-1?"disabled":""}>Next</button></div></div>`},bind(root,ctx){root.querySelectorAll("[data-d]").forEach(b=>b.onclick=()=>{i=Math.max(0,Math.min(cards.length-1,i+Number(b.dataset.d)));ctx.redraw()})},print(){return`<p><em>Picture cards shown one at a time:</em> ${notes.join(" ")}</p>`}};DECKS.push(d);return d}function lab(x,y,t,sz){return`<text x="${x}" y="${y}" font-size="${sz||24}" font-family="Andika,sans-serif" font-weight="700" fill="var(--ink)" text-anchor="middle">${t}</text>`}function tentG(cx,baseY,w,h){const W=w*2,k=W/100;return`<path d="M${cx} ${n1(baseY-h)} Q${n1(cx+W*.1)} ${n1(baseY-h*.94)} ${n1(cx+W*.26)} ${n1(baseY-h*.5)} Q${n1(cx+W*.42)} ${n1(baseY-h*.1)} ${cx+w} ${baseY} H${cx-w} Q${n1(cx-W*.42)} ${n1(baseY-h*.1)} ${n1(cx-W*.26)} ${n1(baseY-h*.5)} Q${n1(cx-W*.1)} ${n1(baseY-h*.94)} ${cx} ${n1(baseY-h)} Z" fill="${RED}" stroke="${INK}" stroke-width="3" stroke-linejoin="round"/><path d="M${n1(cx-W*.17)} ${baseY} V${n1(baseY-h*.3)} Q${cx} ${n1(baseY-h*.62)} ${n1(cx+W*.17)} ${n1(baseY-h*.3)} V${baseY} Z" fill="#2B3A47" stroke="${INK}" stroke-width="2.5" stroke-linejoin="round"/>`+face(cx,baseY-h*.62,k*.5,11,3.6)}function sledG(x,baseY,len){const run=`M${x} ${baseY-4} h${len} q12 0 14 -12`;return`<rect x="${x}" y="${baseY-22}" width="${len}" height="14" rx="6" fill="${GOLD}" stroke="${INK}" stroke-width="3"/><path d="${run}" fill="none" stroke="${INK}" stroke-width="7" stroke-linecap="round"/><path d="${run}" fill="none" stroke="${STEEL}" stroke-width="3.5" stroke-linecap="round"/><line x1="${x+10}" y1="${baseY-9}" x2="${x+10}" y2="${baseY-4}" stroke="${INK}" stroke-width="3" stroke-linecap="round"/><line x1="${x+len-10}" y1="${baseY-9}" x2="${x+len-10}" y2="${baseY-4}" stroke="${INK}" stroke-width="3" stroke-linecap="round"/>`+face(x+len-26,baseY-15,Math.min(.42,len/100*.3),10,3.2)}function crateG(x,y,s){s=s||38;const k=s/100;return`<rect x="${x}" y="${y}" width="${s}" height="${s}" rx="${n1(s*.2)}" fill="${WOOD}" stroke="${INK}" stroke-width="3"/><path d="M${x} ${n1(y+s*.3)} v${n1(-s*.11)} q0 ${n1(-s*.19)} ${n1(s*.19)} ${n1(-s*.19)} h${n1(s*.62)} q${n1(s*.19)} 0 ${n1(s*.19)} ${n1(s*.19)} v${n1(s*.11)} Z" fill="${WOOD_L}" stroke="${INK}" stroke-width="2.5" stroke-linejoin="round"/>`+face(x+s/2,y+s*.6,k*.9,11,3.6)}function flagG(x,baseY,h){return`<line x1="${x}" y1="${baseY}" x2="${x}" y2="${baseY-h}" stroke="${INK}" stroke-width="5" stroke-linecap="round"/><path d="M${x+2} ${baseY-h} Q${x+34} ${baseY-h+3} ${x+50} ${baseY-h+15} Q${x+34} ${baseY-h+27} ${x+2} ${baseY-h+30} Z" fill="${RED}" stroke="${INK}" stroke-width="2.5" stroke-linejoin="round"/>`}function snowGround(w,y,h){return`<rect x="0" y="${y}" width="${w}" height="${h}" rx="14" fill="${ICEF}" stroke="${ICE_D}" stroke-width="2" opacity=".95"/>`}function campFig(){return`<svg viewBox="0 0 560 262" width="540" role="img" aria-label="A camp in the snow. A sled with two crates on it is on the left, a tent is in the middle, and a flag on a pole is on the right.">`+snowGround(560,214,34)+sledG(44,214,156)+crateG(66,159)+crateG(116,159)+tentG(300,214,78,118)+flagG(486,214,108)+lab(122,246,"sled")+lab(300,246,"tent")+lab(498,246,"flag")+`</svg>`}function polesFig(){return`<svg viewBox="0 0 360 286" width="340" role="img" aria-label="Two flag poles in the snow. Pole 1 is short and Pole 2 is tall.">`+snowGround(360,240,30)+flagG(110,240,104)+flagG(250,240,186)+lab(110,276,"Pole 1",26)+lab(250,276,"Pole 2",26)+`</svg>`}function sledsFig(){return`<svg viewBox="0 0 420 206" width="400" role="img" aria-label="Two sleds. Sled A is short and Sled B is long. Both start at the same line on the left."><line x1="52" y1="26" x2="52" y2="190" stroke="var(--line)" stroke-width="3" stroke-dasharray="7 6"/>`+sledG(56,74,124)+lab(118,100,"Sled A",26)+sledG(56,166,250)+lab(181,192,"Sled B",26)+`</svg>`}function shapeCampFig(){return`<svg viewBox="0 0 480 300" width="450" role="img" aria-label="A sun shape above a tent shape, a sled shape below the tent, and a crate shape beside the tent."><circle cx="196" cy="48" r="36" fill="#FBD873" stroke="${INK}" stroke-width="3"/>`+lab(196,54,"sun",22)+`<polygon points="196,104 134,204 258,204" fill="${RED}" stroke="${INK}" stroke-width="3" stroke-linejoin="round"/>`+lab(196,192,"tent",22)+`<rect x="126" y="232" width="140" height="42" rx="6" fill="#8ECBE8" stroke="${INK}" stroke-width="3"/>`+lab(196,259,"sled",22)+`<rect x="334" y="120" width="88" height="88" rx="6" fill="${WOOD}" stroke="${INK}" stroke-width="3"/>`+lab(378,172,"crate",22)+`</svg>`}function linesFig(){const tag=e=>`<span style="font-size:2.5rem;line-height:1" aria-hidden="true">${ic(e,40)}</span>`;const line=(a,t,b)=>`<div style="display:flex;align-items:center;justify-content:space-between;gap:16px">${tag(a)}<span style="${DISP};font-size:clamp(1.8rem,4.6vw,3rem);flex:1;text-align:left">${t}</span>${tag(b)}</div>`;return`<div style="width:fit-content;margin:8px auto 10px;border:6px solid var(--gold-ink);border-radius:16px;background:var(--surface);padding:12px 22px;display:grid;gap:10px">${line(TENT,"We camp on the ice.",SNOW)}${line(FLAG,"The sled is red.",sledPic(58))}</div><p class="small" style="text-align:center">The four pictures are a tent, a snowflake, a flag, and a sled.</p>`}function packChart(){const rows=[[sledPic(64),"sled",CRATE,"food crates"],[SKIS,"skis",SNOW,"fast on snow"],[RADIO,"radio",PHONE,"call for help"]];const cell=(pic,word)=>`<span style="display:inline-block;text-align:center;min-width:106px"><span style="display:block;font-size:3rem;line-height:1.1" aria-hidden="true">${ic(pic,48)}</span><span style="display:block;font-family:var(--font-display);font-weight:700;font-size:1.35rem">${word}</span></span>`;return`<div class="figure" style="gap:16px" role="img" aria-label="Picture chart: sled and food crates, skis and fast on snow, radio and call for help">`+rows.map(r=>`<div style="display:flex;align-items:center;gap:6px;border:3px solid var(--line);border-radius:18px;padding:10px 14px;background:var(--surface)">${cell(r[0],r[1])}<span style="font-size:2rem;font-weight:800;color:var(--sea)" aria-hidden="true">&#8594;</span>${cell(r[2],r[3])}</div>`).join("")+`</div>`}function matchFig(){const box=(a,b)=>`<div style="border:3px solid var(--line);border-radius:18px;background:var(--surface);padding:8px 18px;text-align:left;font-size:2.4rem;line-height:1.4">${a}<br>${b}</div>`;const row=(e,n,sp)=>`<span style="letter-spacing:${sp}" aria-hidden="true">${Array(n).fill(unit(e,42,sp)).join("")}</span>`;const tag=t=>`<p class="fig-label" style="margin:0 0 2px;text-align:left">${t}</p>`;return`<div style="display:grid;gap:12px;justify-content:center;margin:6px 0 12px"><div>${tag("Top box")}${box(row(sealPic(50),5,".12em"),row(FISH,7,".12em"))}</div><div>${tag("Bottom box")}${box(row(TENT,6,".02em"),row(FLAG,6,".5em"))}</div></div>`}function bookFig(){return`<p class="passage" style="${LINE_STYLE}">I see the camp.<br>I see a tent.<br>It is red.<br>I see a sled.<br>A dog can pull.<br>The dog can run.<br>I sit on the sled.<br>I like the camp.</p><div class="figure" style="gap:14px" aria-hidden="true"><span style="font-size:3rem">${ic(TENT,48)}</span>${sledPic(58)}<span style="font-size:3rem">${ic(DOG,48)}</span></div><p class="small">A camp has tents. People sleep there. It is a place. Dogs can pull a sled. It goes on snow.</p>`}function unitFig(){const u=46,y1=56,y2=150;let s=`<svg viewBox="0 0 420 212" width="400" role="img" aria-label="A sled above five blocks laid end to end, and a rope above three blocks laid end to end.">`;s+=sledG(40,y1,5*u);for(let i=0;i<5;i++)s+=`<rect x="${40+i*u}" y="${y1+4}" width="${u}" height="26" fill="${GOLD}" stroke="${INK}" stroke-width="2.5"/>`;s+=lab(312,y1+24,"sled",24);s+=`<path d="M40 ${y2-14} h${3*u}" stroke="${RED}" stroke-width="9" stroke-linecap="round" fill="none"/>`;for(let i=0;i<3;i++)s+=`<rect x="${40+i*u}" y="${y2}" width="${u}" height="26" fill="${GOLD}" stroke="${INK}" stroke-width="2.5"/>`;s+=lab(230,y2+20,"rope",24);s+=`<text x="40" y="202" font-size="20" font-family="Andika,sans-serif" font-weight="700" fill="var(--muted)">Every block is the same size.</text>`;return s+"</svg>"}function crateSplitFig(){let s=`<svg viewBox="0 0 520 268" width="500" role="img" aria-label="Seven wooden crates in a row above two empty sleds, Sled A and Sled B.">`;for(let i=0;i<7;i++)s+=crateG(40+i*64,16,44);s+=lab(260,88,"7 crates",24);s+=snowGround(520,180,40)+sledG(50,180,170)+sledG(290,180,170);s+=lab(135,250,"Sled A",24)+lab(375,250,"Sled B",24);return s+`</svg>`}function teenCratesFig(){let s=`<svg viewBox="0 0 580 262" width="560" role="img" aria-label="A sled loaded with ten wooden crates, and four more crates standing on the snow beside it.">`;s+=snowGround(580,180,40)+sledG(24,180,350);for(let i=0;i<10;i++)s+=crateG(30+i*34,128,30);for(let i=0;i<4;i++)s+=crateG(410+i*40,150,30);s+=lab(199,244,"one full sled",22)+lab(485,244,"more crates",22);return s+`</svg>`}const MIX=[[FISH,70,70],[FISH,230,70],[FISH,390,70],[FISH,150,150],[FISH,310,230],[FISH,70,230],[SNOW,150,70],[SNOW,310,150],[SNOW,70,150],[SNOW,230,230],[FLAG,390,150],[FLAG,230,150],[FLAG,390,230]];function mixScatterFig(){let s=`<svg viewBox="0 0 460 290" width="440" role="img" aria-label="A box with thirteen mixed-up things in it: six fish, four snowflakes and three flags."><rect x="4" y="4" width="452" height="282" rx="22" fill="var(--surface)" stroke="var(--line)" stroke-width="3"/>`;MIX.forEach(m=>{s+=F.picXY(m[1],m[2],m[0],m[0]===SNOW?36:40)||""});return s+`</svg>`}function flatSolidFig(){const cell=x=>`<rect x="${x}" y="10" width="130" height="130" rx="18" fill="var(--surface)" stroke="var(--line)" stroke-width="3"/>`;const sheet=x=>`<rect x="${x}" y="24" width="74" height="102" rx="6" fill="#FFFFFF" stroke="${INK}" stroke-width="3"/>`;let s=`<svg viewBox="0 0 600 190" width="580" role="img" aria-label="Four boxes. Box 1 is a square drawn on a sheet of paper. Box 2 is a wooden crate. Box 3 is a circle drawn on a sheet of paper. Box 4 is a ball.">`;s+=cell(10)+sheet(38)+`<rect x="52" y="48" width="46" height="46" fill="none" stroke="#1b1b1b" stroke-width="5"/>`;s+=cell(160)+crateG(188,40,74);s+=cell(310)+sheet(338)+`<circle cx="375" cy="75" r="24" fill="none" stroke="#1b1b1b" stroke-width="5"/>`;s+=cell(460)+(F.picXY(525,75,BALL,80)||"");[75,225,375,525].forEach((x,i)=>{s+=lab(x,172,String(i+1),26)});return s+`</svg>`}const VS=`<span style="${DISP};font-size:1.5rem;color:var(--muted)" aria-hidden="true">and</span>`;const cmp=picDeck([grp(CRATE,6,3)+VS+grp(FISH,8,4),scatter(FLAG,7,13)+VS+scatter(TENT,5,29),grp(sledPic(56),4,2,"3.4rem")+VS+grp(FISH,7,4,"1.7rem"),grp(SNOW,8,4)+VS+grp(CRATE,8,4),grp(FISH,9,5)+VS+scatter("SEAL",10,41)],["1) 6 crates and 8 fish.","2) 7 flags and 5 tents, mixed up.","3) 4 big sleds and 7 small fish.","4) 8 snowflakes and 8 crates.","5) 9 fish and 10 seals."]);const STOPS=[{id:1,title:"Base Camp Letters",short:"Base Camp",parts:[{title:"Crate Letters",std:["RF.K.1"],kind:"words",full:E.alphabet(),words:NAME_LETTERS,unit:"Letter",n:10,dur:45,dir:"Say the name of each letter.",desc:"naming uppercase and lowercase letters, including look-alike letters",key:["The student says the name of each letter: S, a, G, t, O, f, m, I, p, d. Count a letter correct when the name is right. Sounds are not needed here.","Watch the look-alike pair p and d, and watch capital I. Write down any letters that were missed or mixed up."]},{title:"Two Lines",std:["RF.K.1"],n:3,dur:35,dir:"Look at the two lines. Answer out loud.",desc:"print concepts (counting words and letters)",html:()=>linesFig(),key:["Ask: How many words are in the top line? (5)","Ask: How many words are in the bottom line? (4)","Ask: Look at the first word in the bottom line. How many letters does it have? (3, the word The)"]}]},{id:2,title:"Flag Trail Count",short:"Flag Trail",parts:[{title:"Up the Trail",std:["K.CC.A.1"],n:3,label:"checks met",dur:75,dir:"Count out loud. Start at 1. Go as high as you can.",desc:"counting out loud by ones",html:()=>`<p class="big" style="text-align:center">The team put flags in the snow to mark the trail to the weather station. Count out loud as you walk up the trail.</p><div style="text-align:center;font-size:3rem;letter-spacing:.14em;line-height:1.3" aria-hidden="true">${Array(9).fill(ic(FLAG,48)).join("")}</div>`,key:["Say: Start at 1 and count as high as you can. Check: counts 1 to 20 in order with no skips.","Keeps going from 20 to 40 and gets across each new ten (29 to 30, 39 to 40).","Counts past 50. Stop the student at 100. Write the highest number said before a mistake. The end of year goal is 100."]},{title:"Ten Crates a Sled",std:["K.CC.A.1"],n:2,label:"checks met",dur:45,dir:"Count by tens out loud.",desc:"counting by tens",html:()=>`<div class="figure">${F.pic(CRATE,"","4.6rem")}${F.pic(sledPic(86),"","4.6rem")}</div><p class="big" style="text-align:center">Each sled carries 10 crates. Count by tens to 100.</p>`,key:["Say: Count the crates by tens as the sleds go by. Check: says 10, 20, 30, 40, 50 with no help.","Keeps going: 60, 70, 80, 90, 100. Write the last number said in order."]}]},{id:3,title:"Ice Floe Sounds",short:"Ice Floes",parts:[{title:"Rhyme Floes",std:["RF.K.2"],n:6,dur:60,dir:"Listen to your teacher. Answer out loud.",desc:"hearing rhymes, making a rhyme, and clapping syllables",html:()=>`<div class="figure">${F.pic(EAR)}${F.pic(CLAP)}</div><p class="small" style="text-align:center">An iceberg is a huge piece of ice that floats in the sea.</p>`,key:["Ask: Do snow and go rhyme? (yes)","Ask: Do whale and seal rhyme? (no)","Ask: Which word does not rhyme: fox, box, sea? (sea)","Say: Tell me a word that rhymes with pole. (hole, mole, bowl, goal, or any rhyme. Silly words count.)","Say: Clap the parts in iceberg. (2 claps: ice-berg)","Say: Clap the parts in radio. (3 claps: ra-di-o)"]},{title:"Put It Together",std:["RF.K.2"],n:6,dur:60,dir:"Listen to your teacher. Answer out loud.",desc:"blending spoken sounds and saying the first, last, and all sounds in a word",html:()=>`<div class="figure">${F.pic(TALK)}${F.pic(SNOW)}</div>`,key:["Say: Put these sounds together: /s/ /u/ /n/. (sun)","Say: Put these sounds together: /f/ /l/ /a/ /g/. (flag)","Ask: What is the first sound in tent? (/t/. The sound, not the letter name.)","Ask: What is the first sound in whale? (/w/)","Ask: What is the last sound in sled? (/d/)","Say: Tell me every sound in fog. (/f/ /o/ /g/, three sounds)"]}]},{id:4,title:"Pip on the Ice",short:"Pip Story",parts:[{std:["RL.K.1"],n:4,dur:90,dir:"Listen while your teacher reads the lines. Then answer out loud.",desc:"asking and answering questions about key details in a story read aloud to the student",html:()=>`<div class="figure" aria-hidden="true">${sealPic(100)}<span style="font-size:3.4rem">${ic(SUN,54)}</span></div><p class="passage" style="${LINE_STYLE}">Pip is a seal.<br>Pip sits on the ice.<br>The sun is hot.<br>Pip dips in the sea.</p><p class="small">A seal can swim. It swims in the sea. The sea is cold. It can nap on the ice.</p>`,key:["Read the four lines on the screen out loud to the student two times. Point under each word as you read. The student does not read them. Ask: Who is the story about? (Pip, a seal)","Ask: Where does Pip dip? (in the sea)","Ask: Why does Pip dip in the sea? (the sun is hot)","Say: Now you ask me a question about Pip. Start with What or Where. (asks a real question about the lines, such as: Where is Pip now?)"]}]},{id:5,title:"Supply Crates",short:"Crates",parts:[{title:"More or Fewer",std:["K.CC.C.6"],n:5,dur:75,dir:"Look at the two groups. Answer out loud.",desc:"comparing two groups of objects (more, fewer, the same)",render:()=>cmp.render(),bind:(root,ctx)=>cmp.bind(root,ctx),printHtml:()=>cmp.print(),key:["Card 1. Ask: Are there more crates or more fish? (fish. 8 is more than 6.)","Card 2. Ask: Which group has fewer, the flags or the tents? (the tents. 5 is fewer than 7.)","Card 3. Say: The sleds are big and the fish are small. Ask: Which group has more? (the fish. 7 is more than 4. Size does not change the count.)","Card 4. Ask: Are there more snowflakes, more crates, or the same? (the same, 8 and 8)","Card 5. Ask: Which group has fewer, the fish or the seals? (the fish. 9 is fewer than 10.)"]},{title:"One for Each",std:["K.CC.C.6"],dur:60,dir:"Look at the boxes. Answer out loud.",desc:"matching and counting to tell which group has more, fewer, or the same",fig:()=>matchFig(),qs:["Look at the top box. Is there a fish for every seal?","In the top box, which has more: the seals or the fish?","In the top box, which has fewer: the seals or the fish?","Look at the bottom box. Are there more tents, more flags, or the same?"],key:["Yes. There are 5 seals and 7 fish, so 2 fish are left over.","The fish (7 is more than 5)","The seals (5 is fewer than 7)","The same, 6 and 6. The flags are spread out, but the count is equal."]}]},{id:6,title:"Word Flags",short:"Word Flags",parts:[{title:"Sound Flags",std:["RF.K.3"],kind:"words",words:SOUND_LETTERS,unit:"Letter",n:10,dur:45,dir:"Say the sound each letter makes.",desc:"saying the sounds of letters",key:["The student says the most common sound for each letter: r /r/, A as in apple, s /s/, k /k/, i as in it, N /n/, b /b/, o as in octopus, w /w/, g /g/. The letter name is not needed here.","The long sound for A or i is also fine. Write down any sounds that were missed."]},{title:"Sled Words",std:["RF.K.3"],n:9,dur:60,dir:"Read each word out loud.",desc:"reading high-frequency words and short vowel words",html:()=>wordGrid(["the","my","see","can","it","map","bed","fin","tub"]),key:["High-frequency words the student should know by sight: the, my, see, can, it","Sounds out or reads: map, bed, fin, tub","Score is the number of words read correctly out of 9. Write down which ones were missed."]}]},{id:7,title:"Radio Call",short:"Radio",parts:[{std:["SL.K.2"],n:5,dur:75,dir:"Put your eyes on your teacher and listen. Then answer out loud.",desc:"answering questions about key details in a text read aloud and asking for help",html:()=>`<div class="figure">${F.pic(RADIO)}${F.pic(EAR)}</div><p class="big" style="text-align:center">Listening time. Your teacher will read you a report from the ice camp.</p>`,read:CAMP,key:["Ask: Where did the team land? (on a flat field of snow)","Ask: How many tents did they put up? (four)","Ask: Why were the tents red? (red is easy to see when the snow blows)","Ask: What did they use to mark the path back to camp? (flags on sticks)","Say: Pretend you missed one part. What can you say to me? (asks for help, such as: Can you read that part again? or What is a field?)"]}]},{id:8,title:"Long and Tall",short:"Long or Tall",parts:[{std:["K.MD.A.2"],n:5,dur:75,dir:"Look at the two poles and the two sleds. Answer out loud.",desc:"comparing two objects to tell which has more or less of an attribute and describing the difference",html:()=>`<div class="figure">${polesFig()}${sledsFig()}</div><p class="small" style="text-align:center">Both sleds start at the same dotted line, so you can see which one is longer.</p>`,key:["Ask: Which flag pole is taller? (Pole 2)","Ask: Which flag pole is shorter? (Pole 1)","Ask: Which sled is longer? (Sled B)","Ask: Which sled is shorter? (Sled A)","Say: Tell me about the two poles in one sentence. Use the word taller. (describes the difference, such as: Pole 2 is taller than Pole 1.)"]}]},{id:9,title:"Little Camp Book",short:"Camp Book",parts:[{std:["RF.K.4"],n:32,label:"words read correctly",dur:60,dir:"Point to each word and read it out loud.",desc:"reading a short emergent-reader book with purpose and understanding",html:()=>bookFig(),key:["Count the words the student reads correctly, out of 32, and enter the number in the box. A word the student fixes without help counts. Write down the words that were missed.","Points or tracks under each word, left to right and top to bottom","Reads most of the words correctly, including the sight words I, see, the, is, a, can. No picture words needed by now: camp, tent, sled, dog, pull, run and sit are all sound-out words once blends are taught","Ask: What is this little book about? (the camp, or a dog that pulls a sled)"]}]},{id:10,title:"Camp Shapes",short:"Shapes",parts:[{std:["K.G.A.1"],n:4,dur:60,dir:"Look at the camp made of shapes. Answer out loud.",desc:"naming shapes of objects and telling where they are (above, below, beside)",html:()=>`<div class="figure">${shapeCampFig()}</div>`,key:["Say: Each part of the camp is a shape. Ask: Name the shape of the sun, the tent, the sled, and the crate. (circle, triangle, rectangle, square)","Ask: Which shape is above the tent? (the circle, the sun)","Ask: Which shape is below the tent? (the rectangle, the sled)","Ask: Which shape is beside the tent? (the square, the crate)"]}]},{id:11,title:"Whale Watch",short:"Whales",parts:[{std:["RI.K.1"],n:6,dur:90,dir:"Listen while your teacher reads the lines. Then answer out loud.",desc:"asking and answering questions about key details in an informational text about whales",html:()=>`<div class="figure" aria-hidden="true"><span style="font-size:3.4rem">${ic(WHALE,54)}</span><span style="font-size:3.4rem">${ic(FISH,54)}</span></div><p class="passage" style="${LINE_STYLE}">A whale is in the sea.<br>A whale is big.<br>A whale is not a fish.<br>It comes up for air.<br>It goes up to the top.<br>Whales can sing.</p>`,read:WHALES,key:["Read the six lines on the screen out loud to the student two times. Point under each word as you read. The student does not read them. Ask: Where does a whale live? (in the sea. Line 1.)","Ask: What does a whale come up for? (air. Line 4. The read-aloud also says a whale breathes air, so ask this before you read the longer text aloud.)","Ask: Is a whale a fish? (no. Line 3 says a whale is not a fish.)","Ask: How does a whale take a breath? (it goes up to the top. Line 5.)","Ask: What do some whales do in the sea? (sing. Line 6.)","Say: Ask me a question about whales. Start with What or Where. (asks a real question about whales)","All six scored items come from the lines on the screen. After you score them you may read the longer whale text aloud for interest. It is not scored here."]}]},{id:12,title:"Camp Talk",short:"Talk",parts:[{std:["L.K.1"],n:5,dur:75,dir:"Look at the picture. Listen to your teacher. Say your answer out loud.",desc:"spoken grammar items (plural nouns, question words, position words in complete sentences)",html:()=>`<div class="figure">${campFig()}</div>`,key:["Say: One tent, two ____. (tents)","Say: One dish, two ____. (dishes)","Say: Ask me a question that starts with Where. (asks a where question)","Say: Look at the picture. Where is the sled? Tell me in a whole sentence. (a complete sentence with beside or next to, such as: The sled is beside the tent.)","Say: Where are the crates? Tell me in a whole sentence. (a complete sentence with on, such as: The crates are on the sled.)"]}]},{id:13,title:"Draw and Write",short:"Write",parts:[{std:["W.K.2"],n:3,label:"checks met",dur:150,dir:WRITE_DIR,desc:"an informative draw-and-write piece about a piece of camp gear",html:()=>`<div class="figure">${F.pic(TENT,"tent")}${F.pic(ic(DOG,64)+sledPic(66),"a dog and a sled","4rem")}${F.pic(BOOT,"warm boots")}</div><p class="big">Pick one: a tent, a sled, or warm boots. Draw it. Write its name. Then write or tell one thing about it.</p><p class="small">Dogs can pull a sled. It goes over the snow. Warm boots keep your feet dry. You can walk in deep snow.</p>`,key:["Names what the drawing and writing are about: a tent, a sled, or warm boots. The student may say it, label the picture, or write a letter or word for it.","Gives at least one piece of true information about it, such as: You sleep in a tent. Dogs pull the sled. Boots keep your feet warm.","Uses drawing, telling, or writing (any mix) to get the information across"]}]},{id:14,title:"Field Notes",short:"Field Notes",parts:[{std:["W.K.8"],dur:60,dir:"Look at the chart. Answer out loud.",desc:"answering questions from a picture chart and from experience",fig:()=>packChart(),qs:["Look at the chart. What do we use to carry the food crates?","Look at the chart. What do we use to go fast on the snow?","Look at the chart. What do we use to call for help?","Think about this morning. What is one thing you put on before our meeting?"],key:["The sled. Uses the chart to answer.","The skis. Uses the chart to answer.","The radio. Uses the chart to answer.","Names one real thing, such as socks, a shirt, or shoes. Recalls it from experience."]}]},{id:15,title:"Tell Me More",short:"Tell More",parts:[{std:["SL.K.4"],n:3,label:"checks met",dur:60,dir:"Tell your teacher out loud. Use lots of details.",desc:"describing a familiar place with details",html:()=>`<div class="figure">${F.pic(PARK)}${F.pic(BALL)}${F.pic("books")}</div><p class="big" style="text-align:center">Tell me about a place where you like to play.</p>`,key:["Names the place and tells something about it","Adds a detail when you ask: What do you see there?","Adds another detail when you ask: Who goes there with you, and what do you do?"]}]},{id:16,title:"How Many Fish",short:"How Many",parts:[{std:["K.CC.B.4"],n:3,dur:55,dir:"Look at the two boxes. Count out loud and answer.",desc:"counting a group and telling how many, and knowing the count does not change when the things move or the counting starts somewhere else",html:()=>`<div class="figure">${grp(FISH,8,4)}${scatter(FISH,8,77)}</div><p class="small" style="text-align:center">The second box holds the same fish as the first box. They are just moved around.</p>`,key:["Point to the first box. Say: Count these fish out loud. How many fish are there? (8. The last number said is the answer. If the student counts correctly and then cannot say how many, write that down: the counting is there and the how-many is not yet.)","Point to the second box. Say: These are the same 8 fish, moved around. How many fish are in this box? (8, without counting them again. Counting again and getting 8 is a partial answer; note it.)","Point back to the first box. Say: Now count them starting from the other end. How many? (8. The answer does not change when you count in a different order.)"]}]},{id:17,title:"Fish and Flags",short:"Add and Take",parts:[{std:["K.OA.A.2"],n:3,dur:60,dir:"Listen to your teacher. Use the ten frames if you want. Answer out loud.",desc:"solving addition and subtraction word problems within 10",html:()=>`<div class="figure">${F.pic(sealPic(96),"Pip","4rem")}${F.pic(FISH,"fish")}${F.pic(FLAG,"flags")}</div><p class="small" style="text-align:center">You can count on your fingers, draw, or open the ten frames.</p>`,key:["Say: Pip caught 4 fish in the morning and 3 more fish after lunch. How many fish did Pip catch in all? (7)","Say: There were 9 fish on the ice. A bird carried 2 of them away. How many fish were left? (7)","Say: The team put 5 flags along the trail. Then they put in 4 more. How many flags are on the trail now? (9)","Objects, fingers or a drawing all count. Write down which the student used."]}]},{id:18,title:"Two Sleds",short:"Two Sleds",parts:[{std:["K.OA.A.3"],n:3,dur:60,dir:"Look at the seven crates and the two sleds. Answer out loud.",desc:"breaking 7 into two parts in more than one way and saying the number sentence",fig:()=>crateSplitFig(),key:["Say: All 7 crates go on these two sleds. Tell me one way to split them. How many on Sled A and how many on Sled B? (Any pair that makes 7: 6 and 1, 5 and 2, 4 and 3, 3 and 4, 2 and 5, 1 and 6, or 7 and 0.)","Say: Now tell me a different way. (Any other pair that makes 7. It must be a new pair, not the same one turned around unless the student says so.)","Say: Say the number sentence for one of your ways. (7 equals 4 plus 3, or whichever pair the student chose. Writing it on paper counts too.)","If the student gives one way and cannot find a second, write that down: one decomposition is there and more than one is not yet."]}]},{id:19,title:"Teen Crates",short:"Teen Crates",parts:[{std:["K.NBT.A.1"],n:3,dur:60,dir:"Look at the sled and the crates on the snow. Answer out loud.",desc:"seeing a teen number as one ten and some more ones",fig:()=>teenCratesFig(),key:["Say: A full sled carries 10 crates. This sled is full, and there are more crates on the snow beside it. How many crates are there in all? (14. 10 on the sled and 4 on the snow.)","Say: So 14 is one full sled of ten and how many more? (4 more)","Say: Now picture 17 crates. How many full sleds of ten, and how many crates left on the snow? (1 full sled of ten and 7 left over.)","Counting all 14 one by one is a partial answer. The standard asks the student to see the ten as one group. Write down which the student did."]}]},{id:20,title:"Sort the Finds",short:"Sort",parts:[{std:["K.MD.B.3"],n:3,dur:60,dir:"Look at the box. Answer out loud.",desc:"sorting things into groups, counting each group, and putting the groups in order by how many",fig:()=>mixScatterFig(),key:["Say: The team put everything it found into one box. Sort these into groups by what they are. How many groups do you get? (3 groups: fish, snowflakes and flags.)","Say: How many are in each group? (6 fish, 4 snowflakes, 3 flags)","Say: Now put your groups in order, from the group with the most to the group with the fewest. (fish, then snowflakes, then flags)","If the student sorts and counts but cannot order the groups, write that down: the sorting is there and the ordering by count is not yet."]}]},{id:21,title:"Flat or Solid",short:"Flat or Solid",parts:[{std:["K.G.A.3"],n:3,dur:50,dir:"Look at the four boxes. Answer out loud.",desc:"telling a flat two-dimensional shape from a solid three-dimensional one",fig:()=>flatSolidFig(),key:["Say first: A flat shape is a drawing on a page. It lies down flat. A solid shape is thick, and you could hold it in your hands. Then ask: Which boxes have a flat shape? (1 and 3)","Ask: Which boxes have a solid thing? (2 and 4, the crate and the ball)","Ask: Name the flat shape in box 1 and the flat shape in box 3. (a square and a circle)","The words two-dimensional and three-dimensional are not needed. Flat and solid are enough."]}]},{id:22,title:"Best at the Ice Camp",short:"My Pick",parts:[{std:["W.K.1"],n:3,label:"checks met",dur:75,dir:WRITE_DIR,desc:"an opinion draw-and-write piece naming the topic and stating a preference",html:()=>`<div class="figure">${F.pic(sealPic(96),"a seal","4rem")}${F.pic(WHALE,"a whale")}${F.pic(DOG,"a sled dog")}</div><p class="big">Which one is the best to watch at the ice camp: a seal, a whale, or a sled dog? Draw your pick. Write its name. Then tell me why you picked it.</p>`,key:["Tells the reader what the writing is about, such as: This is about the best animal to watch. The student may say it, label the drawing, or write a letter or word for it.","States an opinion by picking one and saying so, such as: I like the whale best.","Uses drawing, telling, or writing (any mix) to get the opinion across. A reason is a bonus here and is not required for this standard."]}]},{id:23,title:"One Thing I Did",short:"My Story",parts:[{std:["W.K.3"],n:3,label:"checks met",dur:75,dir:WRITE_DIR,desc:"a narrative draw-and-write piece about one event, told in order, with a reaction",html:()=>`<div class="figure">${F.pic(BOOT,"boots")}${F.pic(SNOW,"snow")}${F.pic(PARK,"outside")}</div><p class="big">Think of one thing you did outside. Draw it. Write about it. Then tell me what happened.</p>`,key:["Tells about one thing that really happened, not a list of many things.","Tells what happened in order. Listen for order words such as first, then, next, after that. If none come, ask once: What happened first? What happened next?","Gives a reaction at the end, such as: It was fun, or I was cold. If none comes, ask once: How did you feel about it?"]}]},{id:24,title:"What Living Things Need at Camp",short:"Living Things",parts:[{std:["K-LS1-1"],n:3,dur:75,dir:"Look at both pictures. Answer out loud.",desc:"telling what an animal and a plant need to stay alive",html:()=>`<p class="big">A penguin lives out on the shore. A bean sprout grows in a cup on the tent windowsill.</p>
     <div class="figure">${ic("penguin",96)}${ic("sprout",96)}</div>`,qs:["A penguin stays alive by getting two of these. Which two? Fish to eat, water to drink, or a sled?","The bean sprout in the cup stays alive by getting two of these. Which two? Light, water, or a flag?","The penguin can walk off and find its own food and water. The sprout cannot move at all. So what does somebody at camp have to do for the sprout?"],key:["fish to eat and water to drink. A sled is not something a living thing needs.","light and water. A flag is not something a plant needs.","Bring it water, and keep it where light reaches it. Any answer that names water or light counts. The pattern to listen for is that a plant has to get what it needs right where it stands."]}]},{id:25,title:"Weather at the Ice Camp",short:"Weather",parts:[{std:["K-ESS2-1"],n:3,dur:75,dir:"Look at the week on the board. Count out loud.",desc:"describing a weather pattern from a week of recorded observations",html:()=>`<p class="big">The team writes the weather on the board every morning. Here is one week.</p>
     <table class="chart bigTable" style="margin:14px auto;font-size:1.3rem"><tr><th style="text-align:center">Mon</th><th style="text-align:center">Tue</th><th style="text-align:center">Wed</th><th style="text-align:center">Thu</th><th style="text-align:center">Fri</th><th style="text-align:center">Sat</th></tr>
     <tr><td>${ic("sun",58)}</td><td>${ic("snowCloud",58)}</td><td>${ic("snowCloud",58)}</td><td>${ic("wind",58)}</td><td>${ic("snowCloud",58)}</td><td>${ic("sun",58)}</td></tr></table>`,qs:["Count the days it snowed. How many?","Count the sunny days. How many?","Were there more snowy days or more sunny days this week?"],key:["3","2","more snowy days. 3 is more than 2. The counting is the evidence, so ask the student to touch each day while counting."]},{std:["K-ESS2-2"],n:2,dur:60,dir:"Answer out loud.",desc:"telling how a living thing changes its surroundings to get what it needs",html:()=>`<p class="big">A seal has to come up for air, but the sea is roofed over with thick ice.</p>
     <div class="figure">${ic("seal",88)}${ic("snowflake",88)}</div>`,qs:["The seal scrapes at one spot with its claws and keeps a round hole open in the ice so it can breathe. Did the seal change the ice, or did the ice change the seal?","Tell me one way you change the snow or the dirt outside when you want to play."],key:["The seal changed the ice. It made a hole that was not there before and it keeps the hole open.","Any sensible answer about changing a space on purpose: digging a hole, piling snow into a wall, stamping a path, clearing sticks off a spot, making a track to slide on."]}]},{id:26,title:"Homes, Forecasts and the Ice",short:"Homes",parts:[{std:["K-ESS3-1"],n:3,dur:75,dir:"Match each animal to the place it lives. Answer out loud.",desc:"matching animals to the places that give them what they need",html:()=>`<p class="big">Look at these animals. Each one lives in one place. It gets what it needs.</p>
     <div class="figure">${ic("penguin",80)}${ic("narwhal",80)}${ic("polarBear",80)}</div>
     <p class="big">Here are the places. A nest of pebbles. It is on the shore. The open sea. A den dug in the snow.</p>`,qs:["Where does the penguin keep its eggs?","Where does the narwhal live?","Where does the polar bear make a den?"],key:["a nest of pebbles on the shore","the open sea. Accept the water or under the ice.","in the snow. Accept a snowbank or a drift."]},{std:["K-ESS3-2"],n:2,dur:60,dir:"Answer out loud.",desc:"telling what a weather forecast is for and how people use one to get ready",html:()=>`<p class="big">Before dark the team listens to the forecast for tonight.</p>
     <div class="figure">${ic("radio",88)}${ic("thermometer",88)}</div>`,qs:["The forecast says strong wind and heavy snow tonight. Should the team tie the tents down now, or wait until the wind starts shaking them?","What is a forecast for? To tell what the weather will probably do next, or to tell what the weather did last year?"],key:["tie the tents down now, before the wind comes. Getting ready early is the whole point of a forecast.","to tell what the weather will probably do next"]},{std:["K-ESS3-3"],n:2,dur:60,dir:"Answer out loud.",desc:"telling one way people can take better care of the land and water",html:()=>`<p class="big">The team is packing up to leave the ice.</p>
     <div class="figure">${ic("box",96)}${ic("drop",96)}</div>`,qs:["One person carries the empty cans back to the ship. One person leaves the cans sitting on the snow. Which choice takes better care of the ice and the water?","The team used a whole barrel of water washing dishes. Tell me one way they could use less next time."],key:["carrying the empty cans back to the ship","Any sensible answer: wash in a small bowl instead of under a running tap, scrape the plates first, use the same rinse water twice, turn the tap off while scrubbing."]}]},{id:27,title:"Pushes and Pulls on the Ice",short:"Push and Pull",parts:[{std:["K-PS2-1"],n:3,dur:75,dir:"Answer out loud. Do not say push or pull for the student.",desc:"telling a push from a pull, and comparing a hard push with a gentle one",html:()=>`<p class="big">A push moves something away from you. A pull brings it along with you.</p>
     <div class="figure">${ic("box",88)}${ic("sled",88)}${ic("dog",88)}</div>`,qs:["You put both hands on a heavy supply crate and shove it across the snow away from you. Is that a push or a pull?","The dog team is hitched in front of the sled and runs ahead. The sled comes along behind. Is the sled being pushed or pulled?","You give the crate a soft shove and it slides a little way. Then you shove it hard. What is different about the way it moves?"],key:["a push","pulled","It slides farther, and faster. A stronger push moves a thing farther."]},{std:["K-PS2-2"],n:2,dur:60,dir:"Look at the chart. Answer out loud.",desc:"deciding from test results whether a change made a thing move farther or in a new direction",html:()=>`<p class="big">The team gave the same crate the same shove on two kinds of ground and counted the steps it slid.</p>
     <table class="chart bigTable" style="margin:14px auto;font-size:1.3rem"><tr><th>Ground</th><th style="text-align:center">Steps the crate slid</th></tr>
     <tr><td>smooth ice</td><td>9</td></tr><tr><td>deep soft snow</td><td>2</td></tr></table>`,qs:["Which ground let the crate slide farther?","A sled is gliding straight toward the tent. You give it a shove on its side. What happens to the way it is going?"],key:["smooth ice, 9 steps. Deep snow only let it go 2.","It turns and goes a new way, so it no longer heads at the tent. A push from the side changes the direction."]}]},{id:28,title:"Sun and Shade on the Snow",short:"Sun",parts:[{std:["K-PS3-1"],n:2,dur:60,dir:"Answer out loud. If you can, stand in a sunny spot and a shady spot together first.",desc:"telling what sunlight does to a surface it shines on",html:()=>`<p class="big">Two dark mats are here. Both are laid on the snow. Both went out together. It was the same time. One is in the open sunlight. One is in the shadow. The tent makes it.</p>
     <div class="figure">${ic("sun",88)}${ic("tent",88)}</div>`,qs:["Both mats started out just as cold. One hour later one mat feels warm. Which one, the mat in the sunlight or the mat in the shadow?","The snow under the warm mat has started to melt. The snow under the other mat has not. What did the melting?"],key:["the mat in the sunlight","the sunlight. Accept the sun. It warmed that mat, and the warm mat melted the snow. Accept any answer that names the sun as the warmer."]},{std:["K-PS3-2"],n:2,dur:75,dir:"Draw your answer on your paper and hold it up.",desc:"designing and drawing a cover that keeps a spot out of the sunlight",html:()=>`<p class="big">Here is a crate of fish. The fish is frozen. It is sitting on the sled. The sunlight is bright. The fish starts to thaw. Draw something that keeps the sunlight off the crate, like a tarp held up on poles, a lid, or a wall of snow blocks with a roof.</p>
     <div class="figure">${ic("fish",88)}${ic("skis",88)}</div>`,qs:["Draw your sun cover over the crate.","Point to where the sunlight is coming from and tell me how your cover keeps it off the crate."],key:["Any cover drawn ABOVE or OVER the crate. The three examples are in the direction, so copying one still counts. A wall drawn only beside the crate is partial: ask where the sunlight is coming from.","Something like: it blocks the sun, the sun cannot get to the crate, it puts the crate in a shadow."]}]},{id:29,title:"Solving a Problem at Camp",short:"Solve It",parts:[{std:["K-2-ETS1-1"],n:2,dur:60,dir:"Listen, then answer out loud.",desc:"naming a problem people want to fix and asking a question about it",read:"Juno pushes a thin trail flag into the snow every twenty steps, so the team can find its way back to camp. By lunchtime the wind has blown most of the flags flat, and the trail is very hard to follow.",qs:["What is the problem? The wind blows the trail flags flat, or the flags are orange?","Ask me one question about the flags that would help you fix this."],key:["The wind blows the trail flags flat.","Any real question: how deep do they go in, how hard does the wind blow, how long are the sticks, could two flags hold each other up, is the snow soft there. A statement is not a question, so ask once more."]},{std:["K-2-ETS1-2"],n:2,dur:75,dir:"Draw your answer on your paper and hold it up.",desc:"drawing something whose shape would solve the problem",html:()=>`<p class="big">Draw something that would hold a trail flag up in strong wind, like a deeper hole, a wide foot at the bottom, or stones piled around the stick.</p>
     <div class="figure">${ic("flag",88)}${ic("mountain",88)}</div>`,qs:["Draw your fix.","Tell me what you drew and how its shape keeps the flag standing."],key:["Anything that would steady a stick: a deeper hole, a wide base or foot, a pile of stones or packed snow around it, a second stick tied across, guy lines. The three examples are in the direction, so copying one earns credit.","Naming it is what shows intent. Something like: the stones hold the bottom, the deep hole grips it, the wide foot does not tip."]},{std:["K-2-ETS1-3"],n:2,dur:60,dir:"Look at the chart. Answer out loud.",desc:"comparing test results from two fixes for the same problem",html:()=>`<p class="big">The team tried two fixes and counted how many flags were still standing after the wind.</p>
     <table class="chart bigTable" style="margin:14px auto;font-size:1.3rem"><tr><th>Fix</th><th style="text-align:center">Flags still standing</th></tr>
     <tr><td>pushed in deep with stones at the base</td><td>10</td></tr><tr><td>pushed in shallow, nothing at the base</td><td>2</td></tr></table>`,qs:["Which fix worked better?","How do you know?"],key:["pushed in deep with stones at the base","Because 10 flags were still standing with the stones and only 2 were standing the other way. The reason has to come from the chart, not from liking stones."]}]},{id:30,title:"Rules and Doing Right",short:"Rules",parts:[{std:["HSS-K.1"],n:3,dur:75,dir:"Listen, then answer out loud.",desc:"following rules, knowing what happens when they are broken, and naming an honest choice",read:"Juno wanted to look at the far mountain, so she took the camp telescope off its hook without signing for it. On the way back the lens cap slipped out and sank into the soft snow. Juno dug until she found it, wiped it clean, and went to the camp leader. She said, I took the telescope without signing for it, and I dropped the cap. The leader said thank you for telling me, and showed her where the tool list was.",qs:["What did Juno choose to do? Tell the leader what happened, or hang the telescope back up and say nothing?","One rule at camp is sign for a tool before you take it. What might go wrong if nobody signed for anything?","Tell me one rule in your house, and what would be hard if nobody followed it."],key:["She told the leader what happened.","Nobody would know where things were, two people would want the same tool, something could be lost and nobody would know. Any real consequence counts.","Any rule with a real consequence attached. The consequence is the part to listen for."]}]},{id:31,title:"Maps and Places",short:"Maps",parts:[{std:["HSS-K.4"],n:4,dur:90,dir:"Look at the globe, then the map. Answer out loud.",desc:"telling land from water, using position words on a map, and naming places in a town",html:()=>`<div class="figure"><svg viewBox="0 0 300 180" width="300" height="180" role="img" aria-label="A map showing water around an island with a house and a tree"><rect x="2" y="2" width="296" height="176" rx="14" fill="#BFE3F5" stroke="#6B4A3C" stroke-width="3"/><g stroke="#5E8FA8" stroke-width="3" stroke-linecap="round" fill="none"><path d="M22 34 q10 -8 20 0 t20 0"/><path d="M232 34 q10 -8 20 0 t20 0"/><path d="M22 150 q10 -8 20 0 t20 0"/><path d="M232 150 q10 -8 20 0 t20 0"/><path d="M22 92 q10 -8 20 0 t20 0"/><path d="M232 92 q10 -8 20 0 t20 0"/></g><ellipse cx="150" cy="90" rx="92" ry="54" fill="#A8D49A" stroke="#6B4A3C" stroke-width="3"/><g transform="translate(110,92)"><rect x="-20" y="-6" width="40" height="32" rx="4" fill="#F2E3C6" stroke="#6B4A3C" stroke-width="3"/><path d="M-26 -6 L0 -28 L26 -6 Z" fill="#D9704F" stroke="#6B4A3C" stroke-width="3" stroke-linejoin="round"/><rect x="-7" y="8" width="14" height="18" rx="2" fill="#A8724E" stroke="#6B4A3C" stroke-width="2.4"/></g><g transform="translate(192,92)"><rect x="-6" y="2" width="12" height="24" rx="3" fill="#A8724E" stroke="#6B4A3C" stroke-width="2.6"/><circle cx="0" cy="-8" r="22" fill="#6FB762" stroke="#6B4A3C" stroke-width="3"/></g></svg></div>
     <p class="big">Look at the globe. Blue stands for water. Green and brown stand for land. Look at the camp map. The tent is at the top. The bottom has the fishing hole. The middle has the flag pole. It is drawn between them.</p>
     <p class="big">${ic("tent",56)} the tent &nbsp;&nbsp; ${ic("flag",56)} the flag pole &nbsp;&nbsp; ${ic("fish",56)} the fishing hole</p>`,qs:["Look at the globe. Is there more water or more land?","On the camp map, which one is at the top, the tent or the fishing hole?","Where is the flag pole? Use a word that tells me where it sits.","Name two places you would find in your own town."],key:["more water. The blue covers more of the globe than the green and brown do.","the tent","between the tent and the fishing hole. Accept in the middle. The position word is what is being checked, so a point with no word is partial.","Any two real places: a store, a library, a park, a fire station, a school. The moon does not count."]}]},{id:32,title:"Our Flag and Long Ago",short:"Long Ago",parts:[{std:["HSS-K.2"],n:2,dur:60,dir:"Answer out loud.",desc:"recognizing the flag as a symbol of the country",html:()=>`<div class="figure">${ic("flag",120)}</div>`,qs:["The team plants this one at base camp. What is it called?","Our flag stands for our whole country. Name one place at school or in your town where you have seen it."],key:["a flag. Accept the flag of our country or the American flag.","Any real place: a school, a post office, a park, outside a building, on a coin, at a game."]},{std:["HSS-K.6"],n:3,dur:75,dir:"Answer out loud.",desc:"telling how life long ago was different from life today, and what a commemorative holiday is for",html:()=>`<p class="big">Long ago there were no radios and no phones.</p>
     <div class="figure">${ic("sailboat",96)}${ic("phone",96)}</div>`,qs:["Long ago, how did a traveler send news back home, with a letter carried on a ship for many months, or with a radio?","How would you send news to somebody far away today?","Independence Day comes back every year, and the whole country marks it together. On a day like that, do we remember something that happened long before we were born, or something that happened yesterday?"],key:["with a letter carried on a ship","Any real answer: a phone call, a message, a video call, an email, a letter in the mail. Naming today's way is the then-and-now half of this standard.","something that happened long before we were born. Follow up: what do you think the country remembers on that day? Any reasonable answer counts at this age."]}]}];const LEVELUPS={1:{id:"L1",lv:true,title:"Level Up: Sentence Parts",std:["RF.1.1"],needs:["RF.K.1"],n:3,dir:"Look at the sentence. Answer out loud.",html:()=>`<p class="passage" style="font-size:2.4rem;text-align:center;margin:0 auto;width:fit-content">We ski to the flag.</p><ol class="qlist"><li>Which word is the first word of the sentence?</li><li>Why does that word start with a big letter?</li><li>What mark is at the end of the sentence?</li></ol>`,key:["We","Because it is the first word of the sentence. Sentences start with a capital letter.","A period, or a dot"]},2:{id:"L2",lv:true,title:"Level Up: Count to 120",std:["1.NBT.A.1"],needs:["K.CC.A.1"],n:2,dir:"Count out loud. Then read the numbers.",html:()=>`<ol class="qlist"><li>Start at 114. Count out loud to 120.</li><li>Read each number.</li></ol>${wordGrid(["52","108","120"])}`,key:["114, 115, 116, 117, 118, 119, 120 with no skips. Listen at 119 to 120.","Reads fifty-two, one hundred eight, one hundred twenty"]},4:{id:"L4",lv:true,title:"Level Up: Read a Story",std:["RL.1.1"],needs:["RL.K.1"],n:2,dir:"Read the story out loud. Then answer out loud.",html:()=>`<p class="passage" style="font-size:2rem;line-height:1.8">Nan put on her boots and ran out to the dogs. The dogs barked and wagged their tails. Nan gave each dog a pat. Then she tied them to the sled.</p><ol class="qlist"><li>What did the dogs do when Nan came out?</li><li>What did Nan do after she patted the dogs?</li></ol>`,key:["They barked and wagged their tails","She tied them to the sled"]},6:{id:"L6",lv:true,title:"Level Up: Tricky Words",std:["RF.1.3"],needs:["RF.K.3"],n:3,dir:"Read each word out loud.",html:()=>wordGrid(["ship","that","cake"]),key:["Reads the first word (sh digraph, short i)","Reads the second word (th digraph, short a)","Reads the third word (final e, long a)"]},8:{id:"L8",lv:true,title:"Level Up: Measure It",std:["1.MD.A.2"],needs:["K.MD.A.2"],n:3,dir:"Look at the blocks under the sled and the rope. Answer out loud.",html:()=>`<div class="figure">${unitFig()}</div><ol class="qlist"><li>How many blocks long is the sled?</li><li>How many blocks long is the rope?</li><li>Why do the blocks have to touch, with no gaps?</li></ol>`,key:["5 blocks","3 blocks","Because a gap would make the count wrong. The blocks must sit end to end with no gaps and no overlaps."]}};let npOn={},tfOn={};function npHtml(){let h=`<div class="nl">`;for(let i=1;i<=40;i++)h+=`<button data-n="${i}" class="${npOn[i]?"on":""}">${i}</button>`;return h+`</div><p class="small">Click a number to mark it. Click it again to clear.</p>`}function tfHtml(){return`<div class="tf-wrap">`+[0,1].map(f=>{let c=`<div class="tf">`;for(let i=0;i<10;i++){const k=f*10+i;c+=`<button data-k="${k}" class="c${tfOn[k]||0}" aria-label="Box ${k+1}"><span></span></button>`}return c+"</div>"}).join("")+`</div><p class="small">Click a box to add a red counter. Click again for yellow. Click again to clear.</p>`}const STARTERS={facts:["This is a ____.","It is ____.","People use it to ____."],opinion:["I like ____ best.","I like it because ____."],story:["One day I ____.","Then I ____.","I felt ____."]};const SENTSET={"W.K.1":"opinion","W.K.2":"facts","W.K.3":"story","W.K.8":"facts"};const SENTLAB={opinion:"If you are telling what you like:",facts:"If you are telling facts:",story:"If you are telling a story:"};function sentHtml(st){const parts=st&&st.parts&&st.parts.length?st.parts:st?[st]:[];const sets=[];parts.forEach(p=>(p.std||[]).forEach(c=>{const k=SENTSET[c];if(k&&STARTERS[k]&&sets.indexOf(k)<0)sets.push(k)}));if(!sets.length)sets.push("facts");return sets.map(k=>(sets.length>1?`<p class="small">${SENTLAB[k]}</p>`:"")+`<ul class="starters">${STARTERS[k].map(x=>`<li>${x}</li>`).join("")}</ul>`).join("")}function tpsCmpHtml(){const bar=(y,w,fill,lab2)=>`<rect x="46" y="${y}" width="${w}" height="26" rx="7" fill="${fill}" stroke="var(--fig-ink)" stroke-width="2.5"/><text x="${54+w}" y="${y+14}" font-size="17" dominant-baseline="central" fill="var(--ink)">${lab2}</text>`;const svg=`<svg viewBox="0 0 370 128" width="350" style="max-width:100%" role="img" aria-label="Two bars that both start at the same line. The top bar is longer and the bottom bar is shorter."><line x1="46" y1="14" x2="46" y2="110" stroke="var(--fig-ink)" stroke-width="3" stroke-dasharray="6 5"/>${bar(28,196,"var(--gold)","longer")}${bar(74,112,"var(--gold)","shorter")}<text x="46" y="124" font-size="14" text-anchor="middle" fill="var(--muted)">start</text></svg>`;return`<div class="figure">${svg}</div>`+F.table(["Word","What it means"],[["longer","it goes past the other one"],["shorter","it stops before the other one"],["taller","it goes higher than the other one"],["the same","they both end in the same place"]])+`<p class="small">Line both things up at the same start line. Then look at the other end to see which one goes further.</p>`}const tpsIco=(n,px)=>(F.icon||F.pic2)(n,px)||"";const TPS_ABC=[["a","apple","apple"],["b","bear","bear"],["c","cat","cat"],["d","dog","dog"],["e","egg","egg"],["f","fish","fish"],["g","goat","goat"],["h","hen","hen"],["i","island","island"],["j","jam",""],["k","key","key"],["l","leaf","leaf"],["m","moon","moon"],["n","nose","nose"],["o","octopus","octopus"],["p","pig","pig"],["q","queen",""],["r","rabbit","rabbit"],["s","sun","sun"],["t","tent","tent"],["u","umbrella","umbrella"],["v","van",""],["w","wave","wave"],["x","box, x at the end","box"],["y","yarn",""],["z","zip",""]];function tpsLetterHtml(){const cell=c=>`<div style="display:flex;flex-direction:column;align-items:center;gap:2px;min-width:70px;padding:6px 4px;border:2px solid var(--line);border-radius:10px"><b style="font-size:1.45rem;line-height:1">${c[0]} ${c[0].toUpperCase()}</b>${c[2]?tpsIco(c[2],30):""}<span style="font-size:.9rem;text-align:center">${c[1]}</span></div>`;return`<div class="tool-scroll"><div style="display:flex;flex-wrap:wrap;gap:6px;justify-content:center">${TPS_ABC.map(cell).join("")}</div></div><ul class="frames"><li>Point to a letter and ask for its sound, not its name.</li><li>Rhyme: two words that end with the same sounds, like cat and hat.</li><li>Word parts: clap once for each part you hear. Cam-per is two claps.</li><li>First sound: say only the sound at the start of the word.</li></ul>`}function tpsRetellHtml(){return F.table(["Part","What to tell","Starter"],[["1. First","who was there and where it was","First, ____."],["2. Next","what happened","Then, ____."],["3. Last","how it ended","Last, ____."]])+`<p class="small">Tell the three parts in that order. The card gives the order words, so the student supplies what happened.</p>`}function tpsQwordHtml(){return F.table(["Question word","What it asks about","A question you could ask"],[["Who","a person or an animal","Who helped?"],["What","a thing, or what happened","What did she find?"],["Where","a place","Where did they go?"],["When","a time","When did it start?"],["Why","a reason","Why did it happen?"],["How","the way something is done","How did they fix it?"]])+`<p class="small">Start with one of these words. A question ends with a question mark, and your voice goes up at the end.</p>`}let tpsMaskIdx=0;function tpsMaskLines(){const el=document.querySelector("#stopView .passage");if(!el)return null;const d=document.createElement("div");d.innerHTML=el.innerHTML.replace(/<br\s*\/?>/gi,"\n");const flat=(d.textContent||"").replace(/[ \t]+/g," ");let out=flat.split("\n").map(s=>s.trim()).filter(Boolean);if(out.length<2)out=flat.split(/(?<=[.!?\u201D])\s+/).map(s=>s.trim()).filter(Boolean);return out.length?out:null}function tpsMaskHtml(){const L=tpsMaskLines();if(!L)return`<p class="small">This stop has no passage on the screen to window. Lay a card under the line the student is reading and slide it down one line at a time.</p>`;if(tpsMaskIdx>=L.length)tpsMaskIdx=L.length-1;return`<div class="row center"><button class="chip" data-m="-1">Back</button><button class="chip" data-m="1">Next</button><button class="chip" data-m="0">Start over</button></div><p style="font-family:var(--font-display);font-size:clamp(1.3rem,3.2vw,2rem);line-height:1.6;text-align:center;margin:12px 0">${F.esc(L[tpsMaskIdx])}</p><p class="small">Line ${tpsMaskIdx+1} of ${L.length}. The whole passage stays on the student page. This window is for a student who loses their place, and it reads the first passage on the stop.</p>`}function tpsMaskBind(b,r){b.querySelectorAll("[data-m]").forEach(x=>x.onclick=()=>{const n=(tpsMaskLines()||[""]).length,d=+x.dataset.m;tpsMaskIdx=d?Math.max(0,Math.min(n-1,tpsMaskIdx+d)):0;r()})}const TOOLS={np:{name:"Number line 0 to 20",std:["1.NBT.A.1","1.NBT.B.2","1.OA.A.1","K.CC.A.1","K.CC.B.4","K.CC.C.6","K.MD.B.3","K.NBT.A.1","K.OA.A.2","K.OA.A.3"],html:()=>window.TPNL20(),bind:(b,r)=>window.TPNL20Bind(b,r)},tf:{name:"Ten frames",std:["1.MD.C.4","1.NBT.B.2","1.OA.A.1","K.CC.B.4","K.CC.C.6","K.MD.B.3","K.NBT.A.1","K.OA.A.2","K.OA.A.3"],html:tfHtml,bind:(b,r)=>b.querySelectorAll("[data-k]").forEach(x=>x.onclick=()=>{tfOn[x.dataset.k]=((tfOn[x.dataset.k]||0)+1)%3;r()})},sent:{name:"Sentence starters",std:["W.K.1","W.K.2","W.K.3","W.K.8"],html:sentHtml},cmp:{name:"Longer and shorter card",std:["K.MD.A.2"],html:tpsCmpHtml},letters:{name:"Letter and sound card",std:["RF.K.1","RF.K.2","RF.K.3"],html:tpsLetterHtml},retell:{name:"First, next, last card",std:["SL.K.4","W.K.3"],html:tpsRetellHtml},qwords:{name:"Question word card",std:["K-2-ETS1-1","L.K.1","RI.K.1","RL.K.1","SL.K.2"],html:tpsQwordHtml},mask:{name:"Reading window (one line at a time)",std:["RF.K.4"],html:tpsMaskHtml,bind:tpsMaskBind}};const SUP_CAVEATS=[{t:"np",std:["K.CC.A.1"],msg:"The number line shows the counting order, so counting done with it is supported, not independent."},{t:"sent",msg:"Sentence starters give the student the opening words, so count those checks as supported, not independent."},{t:"passage",std:["RF.K.4"],msg:"If the lines on the screen were read to the student, this part shows listening, not reading. Rate it only if the student read the lines."},{t:"scribe",std:["W.K.2"],msg:"Telling an adult what to write is allowed for W.K.2."},{t:"np",std:["K.CC.B.4","K.OA.A.2","K.NBT.A.1"],msg:"The number line shows the numbers in order, so a count or an answer found by stepping along it is supported, not independent."},{t:"tf",std:["K.OA.A.3","K.NBT.A.1"],msg:"The ten frames show the ten as one filled frame and the parts as counters, which is most of the thinking this standard asks for. Note that the answer was built on a model."},{t:"tf",std:["K.CC.B.4","K.OA.A.2","K.MD.B.3"],msg:"If counters were moved onto the ten frames to count, add or sort, the student worked from a model you built. Note it."},{t:"scribe",std:["W.K.1","W.K.3"],msg:"Telling an adult what to write is allowed for W.K.1 and W.K.3."},{t:"cmp",std:["K.MD.A.2"],msg:"The card supplies the words longer, shorter and taller, so rate on whether the student picks the right one, not on producing the word."},{t:"letters",std:["RF.K.1","RF.K.3"],msg:"The letter and sound card shows a keyword and a picture for each letter, so a sound read off the card is supported, not known by heart."},{t:"letters",std:["RF.K.2"],msg:"RF.K.2 is listening only. If the card was open, note that the student had the rhyme and the clapping rule in front of them."},{t:"retell",std:["SL.K.4","W.K.3"],msg:"The card gives the order words first, then and last, so count the order as supported and rate the details the student supplies."},{t:"qwords",std:["RL.K.1","RI.K.1","L.K.1","SL.K.2","K-2-ETS1-1"],msg:"The card supplies the question words, so a question asked with it open shows the student can use a word that was given, not that they thought of one alone."},{t:"mask",std:["RF.K.4"],msg:"A read with the reading window open is not a clean fluency check. Note in the stop notes that the lines were shown one at a time."}];return{stops:STOPS,levelups:LEVELUPS,tools:TOOLS,supCaveats:SUP_CAVEATS,passageStd:["RF.K.4"],onLeaveStop:()=>{DECKS.forEach(d=>d.reset())}}}});
